"""Writes landing/lms-r3-availability.ts from the app's R-3 lesson packs.

1.37.3 (Ray, 2026-10-16: "if we add soon will it change on its own when
lessons for the third is available?"): the Grades R to 3 kids mode cards
on the landing page show a "Coming soon" pill on every subject the app
ships no lessons for. The one source of truth is the Flutter half's
bundled pack index, lms/dart/templates/assets/r3_packs/index.json, whose
paths are `{subject}/grade{G}/term{T}/{pack}.json`. The Next.js half is
composed apart from the Dart half and cannot read that asset at runtime,
so this script writes what the index implies into a generated TypeScript
file the subjects section imports.

Run it after adding or removing R-3 packs:

    python3 lms/nextjs/scripts/gen_r3_availability.py

`--check` exits 1 (writing nothing) when the committed file is stale.
lms/nextjs/tests/test_landing_apps.py (TestR3Availability) fails the same
way, so a PR that adds packs cannot land without regenerating the file -
and with it the pill flips on its own.
"""

import json
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
SDK_ROOT = os.path.dirname(HERE)
INDEX = os.path.join(SDK_ROOT, os.pardir, "dart", "templates", "assets", "r3_packs", "index.json")
OUTPUT = os.path.join(
    SDK_ROOT, "templates", "components", "custom", "landing", "lms-r3-availability.ts"
)

PACK_RE = re.compile(r"^([a-z0-9_]+)/grade([A-Za-z0-9]+)/term([0-9]+)/[^/]+\.json$")

HEADER = """/*
 * Copyright (c) 2026 ROKCT INTELLIGENCE (PTY) LTD
 *
 * This program is free software: you can redistribute it and/or modify
 * it under the terms of the GNU Affero General Public License as published
 * by the Free Software Foundation, version 3.
 *
 * This program is distributed in the hope that it will be useful,
 * but WITHOUT ANY WARRANTY; without even the implied warranty of
 * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE. See the
 * GNU Affero General Public License for more details.
 *
 * You should have received a copy of the GNU Affero General Public License
 * along with this program. If not, see <https://www.gnu.org/licenses/>.
 */

// GENERATED by lms/nextjs/scripts/gen_r3_availability.py - do not edit.
// What the app's bundled Grades R-3 lesson packs cover
// (lms/dart/templates/assets/r3_packs/index.json), per pack subject id:
// the grade/term pairs with at least one pack. A kids mode subject card
// whose `key` is absent here wears the "Coming soon" pill
// (lms-subjects-section.client.tsx, kidsSubjectSoon). The freshness test
// in lms/nextjs/tests/test_landing_apps.py fails when this file and the
// index disagree.
"""


def availability(packs):
    """Pack subject id -> sorted "gradeG/termT" pairs, from index.json's paths."""
    found = {}
    for path in packs:
        match = PACK_RE.match(path)
        if not match:
            raise ValueError(f"unexpected R-3 pack path in index.json: {path!r}")
        subject, grade, term = match.groups()
        found.setdefault(subject, set()).add(f"grade{grade}/term{term}")

    def order(pair):
        grade, term = pair.split("/")
        g = grade[len("grade"):]
        return (-1 if g == "R" else int(g) if g.isdigit() else 99, int(term[len("term"):]))

    return {subject: sorted(pairs, key=order) for subject, pairs in sorted(found.items())}


def render(packs):
    data = availability(packs)
    lines = [HEADER]
    lines.append("/** R-3 pack subject id -> the grade/term pairs the app ships packs for. */")
    lines.append("export const R3_PACK_AVAILABILITY: Readonly<Record<string, readonly string[]>> = {")
    for subject, pairs in data.items():
        lines.append(f"  {subject}: [{', '.join(json.dumps(p) for p in pairs)}],")
    lines.append("};")
    lines.append("")
    lines.append("/** The R-3 pack subject ids with at least one pack, sorted. */")
    lines.append(
        "export const R3_SUBJECTS_WITH_PACKS: readonly string[] = ["
        + ", ".join(json.dumps(s) for s in data)
        + "];"
    )
    return "\n".join(lines) + "\n"


def load_packs(index=INDEX):
    with open(index, encoding="utf-8") as f:
        return json.load(f)["packs"]


def main(argv):
    text = render(load_packs())
    if "--check" in argv:
        try:
            with open(OUTPUT, encoding="utf-8") as f:
                current = f.read()
        except FileNotFoundError:
            current = None
        if current != text:
            print(f"{os.path.relpath(OUTPUT)} is stale: run {os.path.relpath(__file__)}")
            return 1
        return 0
    with open(OUTPUT, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print(f"wrote {os.path.relpath(OUTPUT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
